'use server'

import { revalidatePath } from 'next/cache'

// Simulated database - in a real app, this would be a database query
let notificationPreference = false

export async function toggleNotification() {
  // Toggle the notification preference
  notificationPreference = !notificationPreference

  // Refresh the current page to show updated preference
  revalidatePath('/')

  return notificationPreference
}

export async function getNotificationPreference() {
  return notificationPreference
}

