args.new_string:
import { toggleNotification, getNotificationPreference } from './actions'

export default async function Home() {
  const notificationsEnabled = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <div>
        <p>Notifications: {notificationsEnabled ? 'ON' : 'OFF'}</p>
        <form action={toggleNotification}>
          <button type="submit">
            Toggle Notifications
          </button>
        </form>
      </div>
    </main>
  );
}

